fmt(format) as (values ('IPL'),('T20'),('ODI')),
calc as (
  select b.*, f.format,
    least(99, greatest(45, b.r
      + case
          when f.format in ('IPL','T20') then case b.sub when 'Finisher' then 3 when 'WK-Finisher' then 3 when 'Middle order' then -1 when 'Pace' then 1 when 'Medium pace' then 1 when 'Batting AR (pace)' then 1 when 'Batting AR (spin)' then 1 else 0 end
          else case b.sub when 'Top order' then 2 when 'Middle order' then 3 when 'Finisher' then -4 when 'WK-Finisher' then -2 when 'Spin' then 2 when 'Bowling AR (spin)' then 1 when 'Medium pace' then -1 else 0 end
        end
      + ((abs(hashtext(b.name || f.format)) % 5) - 2))) as rating
  from base b cross join fmt f
)
select name, country, format, role, sub,
  hand,
  case
    when sub in ('Pace') then (case when name in ('Mitchell Starc','Shaheen Afridi','Trent Boult','Arshdeep Singh','Mohsin Khan') then 'Left-arm fast' else 'Right-arm fast' end)
    when sub in ('Medium pace') then (case when name in ('Mustafizur Rahman','T Natarajan','Yash Dayal','Khaleel Ahmed','Fazalhaq Farooqi') then 'Left-arm medium' else 'Right-arm medium-fast' end)
    when sub = 'Spin' then (case when name in ('Kuldeep Yadav','Noor Ahmad','Tabraiz Shamsi') then 'Left-arm wrist spin' when name in ('Sai Kishore','Keshav Maharaj') then 'Left-arm orthodox' when name in ('Yuzvendra Chahal','Adam Zampa','Adil Rashid','Ravi Bishnoi','Ish Sodhi','Rahul Chahar','Suyash Sharma') then 'Leg spin' else 'Off spin / mystery' end)
    when sub like '%(pace)' then (case when name in ('Sam Curran','Marco Jansen') then 'Left-arm medium-fast' else 'Right-arm medium-fast' end)
    when sub like '%(spin)' then (case when name in ('Ravindra Jadeja','Axar Patel','Mitchell Santner','Shakib Al Hasan','Krunal Pandya','Rachin Ravindra','Kamindu Mendis') then 'Left-arm orthodox' when name in ('Rashid Khan','Wanindu Hasaranga','Liam Livingstone') then 'Leg spin' else 'Off spin' end)
    else 'None'
  end,
  rating,
  (case when rating >= 90 then 2.0 when rating >= 82 then 1.5 when rating >= 72 then 1.0 when rating >= 60 then 0.5 else 0.2 end)
  + (case when rating >= 72 and (
        (format in ('IPL','T20') and sub in ('Finisher','WK-Finisher','Pace','Medium pace'))
     or (format = 'ODI' and sub in ('Top order','Middle order','Spin','Bowling AR (spin)'))) then 0.25 else 0 end),
  case when country = 'India' then 'Indian' else 'Overseas' end,
  age,
  case when rating >= 90 then 'Marquee' when rating >= 82 then 'A' when rating >= 72 then 'B' when rating >= 60 then 'C' else 'Uncapped' end,
  upper(left(split_part(name,' ',1),1) || left(split_part(name,' ',2),1))
from calc;
